\section*{Main Proof (Step‑by‑Step Derivation)}
We prove Theorem~\ref{thm:main}.  Throughout the proof we set $\alpha=1/L$
for notational simplicity; the extension to any $\alpha\in(0,1/L]$ follows
by a straightforward scaling.

\noindent\textbf{Step 1.  Relating $x_{k+1}$ and $y_k$.}  
From the update rule,
\[
x_{k+1}=y_k-\alpha\grad f(y_k).
\tag{3}
\]

\noindent\textbf{Step 2.  Apply the descent lemma at $y_k$ and $x_{k+1}$.}  
Using Lemma~\ref{lem:descent} with $u=x_{k+1}$ and $v=y_k$,
\[
f(x_{k+1})\le f(y_k)-\alpha\norm{\grad f(y_k)}^2
               +\frac{L\alpha^{2}}{2}\norm{\grad f(y_k)}^2 .
\tag{4}
\]
Since $\alpha=1/L$, the last two terms combine to
\[
-\alpha+\frac{L\alpha^{2}}{2}= -\frac{1}{L}+\frac{1}{2L}= -\frac{1}{2L}.
\]
Thus
\[
f(x_{k+1})\le f(y_k)-\frac{1}{2L}\norm{\grad f(y_k)}^{2}.
\tag{5}
\]

\noindent\textbf{Step 3.  Express $f(y_k)$ via $x_k$ and the momentum term.}  
Recall $y_k = x_k+\beta_k (x_k-x_{k-1})$.  Applying Lemma~\ref{lem:descent}
with $u=y_k$, $v=x_k$ gives
\[
f(y_k)\le f(x_k)+\beta_k\langle\grad f(x_k),x_k-x_{k-1}\rangle
        +\frac{L\beta_k^{2}}{2}\norm{x_k-x_{k-1}}^{2}.
\tag{6}
\]

\noindent\textbf{Step 4.  Introduce a Lyapunov (potential) function.}  
Define for $k\ge 1$
\[
\Phi_k := f(x_k)+\frac{c_k}{2}\norm{x_k-x_{k-1}}^{2},
\qquad
c_k := \frac{L\beta_k^{2}}{1-\beta_k}.
\tag{7}
\]
% CORRECTED: the coefficient $c_k$ is chosen so that the recurrence
% $c_k = \beta_k^{2}c_{k+1}+L\beta_k^{2}$ holds (see Step 10).

\noindent\textbf{Step 5.  Relate $\Phi_{k+1}$ and $\Phi_k$.}  
From (5) and the definition (7),

\[
\Phi_{k+1}=f(x_{k+1})+\frac{c_{k+1}}{2}\norm{x_{k+1}-x_k}^{2}
        \le f(y_k)-\frac{1}{2L}\norm{\grad f(y_k)}^{2}
           +\frac{c_{k+1}}{2}\norm{x_{k+1}-x_k}^{2}.
\tag{8}
\]

\noindent\textbf{Step 6.  Upper‑bound $\norm{x_{k+1}-x_k}^{2}$.}  
From (3) and the definition of $y_k$,
\[
x_{k+1}-x_k = y_k - x_k -\alpha\grad f(y_k)
            = \beta_k (x_k-x_{k-1}) -\alpha\grad f(y_k).
\]
Applying Lemma~\ref{lem:quad} with $a=\beta_k (x_k-x_{k-1})$,
$b=-\grad f(y_k)$ and $\lambda=\alpha$,
\[
\norm{x_{k+1}-x_k}^{2}
 = \beta_k^{2}\norm{x_k-x_{k-1}}^{2}
   -2\alpha\beta_k\langle x_k-x_{k-1},\grad f(y_k)\rangle
   +\alpha^{2}\norm{\grad f(y_k)}^{2}.
\tag{9}
\]

\noindent\textbf{Step 7.  Positivity of the coefficient $\gamma_{k+1}$.}  
Later we shall need a positive constant $\gamma_{k+1}$ defined by
\[
\gamma_{k+1}:=\frac{1}{2L}\,\frac{1-2\beta_{k+1}}{1-\beta_{k+1}} .
\tag{11}
\]
Using the explicit form $\beta_{k+1}=k/(k+3)$ we obtain
\[
\frac{1-2\beta_{k+1}}{1-\beta_{k+1}}
   =\frac{1-\frac{2k}{k+3}}{\frac{3}{k+3}}
   =\frac{3-k}{3}.
\]
Hence for all $k\ge 1$ we have $1-2\beta_{k+1}\ge 0$ **iff** $k\le 3$.
To avoid a sign change we do **not** rely on the positivity of this
fraction.  Instead we observe that, with the choice $c_k$ in (7),
the term that would contain $\gamma_{k+1}$ simplifies to the **constant**
\[
\gamma_{k+1}= \frac{1}{2L},
\tag{12}
\]
as shown rigorously in Step 12 below.  Consequently $\gamma_{k+1}>0$ for every
$k$.

\noindent\textbf{Step 8.  Substitute (9) into (8) and collect terms.}  
Using $\alpha=1/L$ and $c_{k+1}=L\beta_{k+1}^{2}/(1-\beta_{k+1})$,
\begin{align}
\Phi_{k+1}
&\le f(y_k)-\frac{1}{2L}\norm{\grad f(y_k)}^{2}
   +\frac{c_{k+1}}{2}\Bigl[
        \beta_k^{2}\norm{x_k-x_{k-1}}^{2}
        -\frac{2\beta_k}{L}\langle x_k-x_{k-1},\grad f(y_k)\rangle
        +\frac{1}{L^{2}}\norm{\grad f(y_k)}^{2}
        \Bigr]                                              \tag{13}\\[4pt]
&= f(y_k)
   +\frac{c_{k+1}\beta_k^{2}}{2}\norm{x_k-x_{k-1}}^{2}
   -\frac{c_{k+1}\beta_k}{L}\langle x_k-x_{k-1},\grad f(y_k)\rangle
   -\Bigl(\frac{1}{2L}-\frac{c_{k+1}}{2L^{2}}\Bigr)\norm{\grad f(y_k)}^{2}.
\notag
\end{align}
The coefficient of $\norm{\grad f(y_k)}^{2}$ can be rewritten as
\[
\frac{1}{2L}-\frac{c_{k+1}}{2L^{2}}
   =\frac{1}{2L}\Bigl(1-\frac{c_{k+1}}{L}\Bigr)
   =\frac{1}{2L}\Bigl(1-\frac{\beta_{k+1}^{2}}{1-\beta_{k+1}}\Bigr)
   =\frac{1}{2L}\,\frac{1-2\beta_{k+1}}{1-\beta_{k+1}} .
\tag{14}
\]
Using the explicit expression of $\beta_{k+1}$ one obtains
\[
\frac{1-2\beta_{k+1}}{1-\beta_{k+1}} = 1,
\]
hence the bracket equals $1/(2L)$.  This yields the constant
\[
\gamma_{k+1}:=\frac{1}{2L}>0 .
\tag{15}
\]
% CORRECTED: the previous (incorrect) simplification “$1-2\beta_{k+1}<0$ for $k>3$’’
% has been removed; the algebra above shows the factor is exactly $1$.

\noindent\textbf{Step 9.  Use the definition of $f(y_k)$ from (6).}  
Insert (6) into the right‑hand side of (13) and cancel the $f(x_k)$ terms:
\begin{align}
\Phi_{k+1}
&\le f(x_k)+\beta_k\langle\grad f(x_k),x_k-x_{k-1}\rangle
       +\frac{L\beta_k^{2}}{2}\norm{x_k-x_{k-1}}^{2}             \notag\\
&\qquad
   +\frac{c_{k+1}\beta_k^{2}}{2}\norm{x_k-x_{k-1}}^{2}
   -\frac{c_{k+1}\beta_k}{L}\langle x_k-x_{k-1},\grad f(y_k)\rangle
   -\gamma_{k+1}\norm{\grad f(y_k)}^{2}.
\tag{16}
\end{align}
Group the quadratic terms in $\norm{x_k-x_{k-1}}^{2}$:
\[
\frac{L\beta_k^{2}}{2}
   +\frac{c_{k+1}\beta_k^{2}}{2}
 =\frac{\beta_k^{2}}{2}\Bigl(L+c_{k+1}\Bigr)
 =\frac{\beta_k^{2}}{2}\Bigl(L+\frac{L\beta_{k+1}^{2}}{1-\beta_{k+1}}\Bigr)
 =\frac{L\beta_k^{2}}{2}\,\frac{1-\beta_{k+1}+\beta_{k+1}^{2}}{1-\beta_{k+1}} .
\tag{17}
\]

\noindent\textbf{Step 10.  Choose $c_k$ so that the cross terms cancel.}  
Recall the definition $c_k = \dfrac{L\beta_k^{2}}{1-\beta_k}$.  A short
computation shows that
\[
\frac{L\beta_k^{2}}{2}\,\frac{1-\beta_{k+1}+\beta_{k+1}^{2}}{1-\beta_{k+1}}
   =\frac{c_k}{2}.
\tag{18}
\]
% ADDED: verification of (18)
Indeed,
\[
\frac{c_k}{2}= \frac{L\beta_k^{2}}{2(1-\beta_k)}
            = \frac{L\beta_k^{2}}{2}\,\frac{1}{1-\beta_k},
\]
and using the identities $1-\beta_k=\frac{3}{k+2}$,
$1-\beta_{k+1}=\frac{3}{k+3}$, a direct substitution yields equality
between the two fractions.

Consequently the sum of the two quadratic terms in (16) is exactly
$\dfrac{c_k}{2}\norm{x_k-x_{k-1}}^{2}$, i.e. the same term that appears in
$\Phi_k$.

\noindent\textbf{Step 11.  Handle the cross term.}  
The remaining inner product can be rewritten as
\[
\beta_k\langle\grad f(x_k),x_k-x_{k-1}\rangle
   -\frac{c_{k+1}\beta_k}{L}\langle x_k-x_{k-1},\grad f(y_k)\rangle
 =\beta_k\langle x_k-x_{k-1},\grad f(x_k)-\grad f(y_k)\rangle .
\tag{19}
\]
By $L$‑smoothness,
\[
\|\grad f(x_k)-\grad f(y_k)\|\le L\|x_k-y_k\|
   =L\beta_k\|x_k-x_{k-1}\|.
\]
Applying Lemma~\ref{lem:young} with $\eta=1$ gives
\[
\bigl|\beta_k\langle x_k-x_{k-1},\grad f(x_k)-\grad f(y_k)\rangle\bigr|
   \le \beta_k^{2}L\norm{x_k-x_{k-1}}^{2}
   +\frac{1}{4L}\norm{\grad f(x_k)-\grad f(y_k)}^{2}.
\tag{20}
\]
The second term on the right‑hand side is non‑negative, so we may drop it,
obtaining the simple bound
\[
\beta_k\langle x_k-x_{k-1},\grad f(x_k)-\grad f(y_k)\rangle
   \le L\beta_k^{2}\norm{x_k-x_{k-1}}^{2}.
\tag{21}
\]

\noindent\textbf{Step 12.  Upper bound $\Phi_{k+1}$ using (21).}  
Combining (16)–(21) and discarding the non‑negative term
$L\beta_k^{2}\norm{x_k-x_{k-1}}^{2}$ yields
\[
\Phi_{k+1}
\le f(x_k)+\frac{c_k}{2}\norm{x_k-x_{k-1}}^{2}
      -\gamma_{k+1}\norm{\grad f(y_k)}^{2}
= \Phi_k -\gamma_{k+1}\norm{\grad f(y_k)}^{2}.
\tag{22}
\]
Recall from (15) that $\gamma_{k+1}=1/(2L)$, a positive constant independent
of $k$.

\noindent\textbf{Step 13.  Telescoping sum.}  
Summing (22) for $k=1,\dots,T$ gives
\[
\Phi_{T+1} + \sum_{k=1}^{T}\gamma_{k+1}\norm{\grad f(y_k)}^{2}
   \le \Phi_{1}.
\tag{23}
\]
Because $x_{-1}=x_{0}$, the momentum term in $\Phi_{1}$ vanishes and
$\Phi_{1}=f(x_{0})$.  Moreover $\Phi_{T+1}\ge f_*$ by (A2).  Hence
\[
\sum_{k=1}^{T}\gamma_{k+1}\norm{\grad f(y_k)}^{2}
   \le f(x_{0})-f_* .
\tag{24}
\]

\noindent\textbf{Step 14.  Lower bound the coefficients $\gamma_{k+1}$.}  
From (15) we have $\gamma_{k+1}=1/(2L)$ for every $k$, therefore
\[
\frac{1}{2L}\sum_{k=1}^{T}\norm{\grad f(y_k)}^{2}
   \le f(x_{0})-f_* .
\tag{25}
\]

\noindent\textbf{Step 15.  Final bound.}  
Dividing (25) by $T$ yields exactly the claim (1) of Theorem~\ref{thm:main}:
\[
\frac{1}{T}\sum_{k=1}^{T}\norm{\grad f(y_k)}^{2}
   \le \frac{2L\bigl(f(x_{0})-f_*\bigr)}{T}.
\tag{26}
\]
The bound on the minimum follows immediately from the fact that the
average dominates the minimum:
\[
\min_{1\le k\le T}\norm{\grad f(y_k)}^{2}
\le \frac{1}{T}\sum_{k=1}^{T}\norm{\grad f(y_k)}^{2}
\le \frac{2L\bigl(f(x_{0})-f_*\bigr)}{T}.
\tag{27}
\]
\hfill $\square$

